    total, results, _timings, _approx = _query_first_then_count(
        secop_client, state["dataset_id"], count_soql, soql
    )
    if results:
        return _with_timing(
            state,
            "degrade_ms",
            start,
            results=results,
            total_count=total,
            degraded=True,
            degraded_hint=hint,
            query_error="",
        )
except Exception:
    pass

try:
    cards = deps.formatter.to_rows(
        [dict(r)], ds,
        {"intent_type": "direct_lookup", "route_reason": "entity_ref_disambiguation"},
        reference_instant=reference_instant_utc,
    )
    if cards:
        estado = _estado_visible(cards[0]) or estado
        nota_estado = _estado_raw_nota(cards[0])
except Exception:
    # Best-effort: una fila legacy o formatter parcial conserva el
    # texto raw previo sin romper toda la desambiguación.
    pass

try:
    from app.core.contextual_suggestions import compute_contextual_filters
    computed = compute_contextual_filters(
        raw_results,
        result["dataset_id"],
        result.get("resolved_params", {}),
    )
    result["contextual_filters"] = computed
except Exception:
    pass  # best-effort, never block the main flow

try:
    total = run_radar(deps, store, radar).total
except Exception:
    pass

try:
    from app.core.contextual_suggestions import compute_contextual_filters
    result["contextual_filters"] = compute_contextual_filters(
        results, ds_id, params,
    )
except Exception:
    pass

